package com.termux.app.workspace;
import android.app.*;import android.widget.*;import com.termux.R;import com.termux.app.TermuxActivity;import com.termux.terminal.TerminalSession;import java.lang.reflect.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class,shadows=AgentSpeechServiceTest.Engine.class) public class AgentDictationLifecycleTest {
 static Object get(Object target,String name)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}static void set(Object target,String name,Object value)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);f.set(target,value);}
 @Test public void allAgentsUseDefaultServiceAndOnlyEditTheirOwnDraft()throws Exception{TermuxActivity a=Robolectric.buildActivity(TermuxActivity.class).get();a.setTheme(R.style.Theme_Termux_Black);a.setContentView(R.layout.activity_termux);set(a,"mTerminalView",a.findViewById(R.id.terminal_view));AgentSpeechServiceTest.configure(a);WorkspaceController c=new WorkspaceController(a);try{WorkspaceStore store=(WorkspaceStore)get(c,"store");AgentDictation d=(AgentDictation)get(c,"dictation");EditText input=(EditText)get(c,"terminalInput");for(String agent:new String[]{"codex","claude","gemini","opencode"}){WorkspaceStore.Session p=new WorkspaceStore.Session();p.environment=agent.equals("codex")?"codex":"ubuntu";p.claudeAgent=agent.equals("claude");p.geminiAgent=agent.equals("gemini");p.aiAgent=agent.equals("opencode")?"opencode":"";TerminalSession fake=new TerminalSession("unused","unused",new String[0],new String[0],2000,null);p.handle=fake.mHandle;store.sessions.add(p);a.getTerminalView().mTermSession=fake;input.setText("existing");d.start();AgentSpeechServiceTest.Engine.listener.onResults(AgentSpeechServiceTest.words("new"));assertEquals("existing new",input.getText().toString());assertTrue(store.recentCommands.isEmpty());assertNull(Shadows.shadowOf(a).getNextStartedActivityForResult());d.start();a.getTerminalView().mTermSession=null;input.setText("other");AgentSpeechServiceTest.Engine.listener.onResults(AgentSpeechServiceTest.words("late"));assertEquals("other",input.getText().toString());}}finally{a.getTerminalView().mTermSession=null;c.close();a.finish();}}
}
